def solve(coins, amount):
    """Fewest coins summing to amount (unlimited supply each), or -1 if impossible."""
    if amount == 0:
        return 0
    usable = [c for c in coins if c > 0]
    INF = float('inf')
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in usable:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

