import heapq

def solve(n, edges):
    """Return the smallest total weight of a path from 0 to n-1 in an
    undirected graph with positive edge weights, or -1 if unreachable."""
    if n <= 1:
        return 0
    adj = [[] for _ in range(n)]
    for a, b, w in edges:
        adj[a].append((b, w))
        adj[b].append((a, w))
    INF = float('inf')
    dist = [INF] * n
    dist[0] = 0
    pq = [(0, 0)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        if u == n - 1:
            return d
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return -1 if dist[n - 1] == INF else dist[n - 1]

